<?php
require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/functions.php';$pdo=aep_database();$matters=$pdo->query('SELECT id,matter_reference,subject FROM matters ORDER BY updated_at DESC')->fetchAll();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){aep_validate_csrf();$title=aep_post_string('title',300);$date=aep_post_string('due_date',10);if($title===''||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)){$error='Title and a valid deadline date are required.';}else{$pdo->prepare('INSERT INTO deadlines(matter_id,title,due_date,priority)VALUES(?,?,?,?)')->execute([(int)($_POST['matter_id']??0)?:null,$title,$date,aep_valid_status(aep_post_string('priority',20),['low','normal','high','urgent'],'normal')]);aep_log_activity($pdo,'Deadlines','Created '.$title);header('Location:'.((int)($_POST['matter_id']??0)?'matter_view.php?id='.(int)$_POST['matter_id']:'dashboard.php'));exit;}}$pageTitle='Create Deadline | AEP';$activeNav='workspace';require __DIR__.'/includes/header.php';?><div class="card" style="max-width:760px;margin:auto"><h1>Add Deadline</h1><?php if($error):?><p style="color:#b42318"><?php echo aep_h($error);?></p><?php endif;?><form method="post" class="grid grid-2" style="margin-top:18px"><?php echo aep_csrf_field();?><div><label>Deadline *</label><input required name="title"></div><div><label>Due date *</label><input required type="date" name="due_date"></div><div><label>Matter</label><select name="matter_id"><option value="">Unlinked deadline</option><?php foreach($matters as $matter):?><option value="<?php echo $matter['id'];?>" <?php echo (int)($_GET['matter_id']??0)===(int)$matter['id']?'selected':'';?>><?php echo aep_h($matter['matter_reference'].' — '.$matter['subject']);?></option><?php endforeach;?></select></div><div><label>Priority</label><select name="priority"><option>normal</option><option>high</option><option>urgent</option><option>low</option></select></div><div><button class="btn">Add deadline</button></div></form></div><?php require __DIR__.'/includes/footer.php';?>
